func (v ScheduledFrequencyValue) Equal(o attr.Value) bool {
	other, ok := o.(ScheduledFrequencyValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.DaysOfMonth.Equal(other.DaysOfMonth) {
		return false
	}

	if !v.DaysOfWeek.Equal(other.DaysOfWeek) {
		return false
	}

	if !v.EndDate.Equal(other.EndDate) {
		return false
	}

	if !v.Hour.Equal(other.Hour) {
		return false
	}

	if !v.IntervalHours.Equal(other.IntervalHours) {
		return false
	}

	if !v.Minute.Equal(other.Minute) {
		return false
	}

	if !v.QuarterlyRecurrence.Equal(other.QuarterlyRecurrence) {
		return false
	}

	if !v.StartDate.Equal(other.StartDate) {
		return false
	}

	if !v.TimeZoneIdentifier.Equal(other.TimeZoneIdentifier) {
		return false
	}

	if !v.ScheduledFrequencyType.Equal(other.ScheduledFrequencyType) {
		return false
	}

	if !v.WeeklyRecurrence.Equal(other.WeeklyRecurrence) {
		return false
	}

	return true
}

